-- 0041 — Authorisation for the two long functions
--
-- Split from 0038 only because these two bodies are long enough that mixing them with the
-- short fixes would bury them. The reasoning is identical: `SECURITY DEFINER` means RLS does
-- not apply inside these functions, so the check has to be written into the body.
--
-- Both are reproduced in full because CREATE OR REPLACE requires the whole definition. They
-- were generated by injecting the guards into the committed text rather than retyped, so the
-- unchanged parts are byte-identical to migrations 0028 and 0024. Verify with:
--
--     git show HEAD:backend/supabase/migrations/0028_allocation.sql
--
-- ── fn_run_allocation ──
-- Had no authorisation check at all. It writes a decision row for every applicant in the
-- cycle, so an unauthorised run is not a read — it is the entire outcome of the induction,
-- rewritten. Gated on `allocation.run`, which only super_admin holds (migration 0008).
--
-- ── fn_submit_evaluation ──
-- Three defects, none of which the live route exercised, and all of which the function is
-- responsible for regardless (R-032):
--   1. `p_interviewer_id` was trusted, so an evaluation could be attributed to another
--      panel member.
--   2. `panel_members.left_at` was ignored, so a removed interviewer could still score.
--      fn_claim_next checks it; these two must agree.
--   3. Recusals were not checked on submit, only on claim.
--
-- Refs: FR-DEC-004, FR-DEC-006, FR-INT-004, FR-INT-006, FR-INT-008, FR-QUE-007,
--       rules.md R-029, R-032, audit C-2, M-8

BEGIN;

CREATE OR REPLACE FUNCTION fn_run_allocation(p_cycle_id uuid)
RETURNS allocation_runs
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_blockers    int;
  v_run         allocation_runs;
  v_score_run   uuid;
  v_proposals   int;
  v_version     int;
  v_checksum    text;
  v_selected    int;
  v_waitlisted  int;
  v_rejected    int;
BEGIN
  -- Allocation writes every decision in the cycle. It had no authorisation check whatsoever:
  -- any caller who could reach the function could run it. Checked before the advisory lock so
  -- an unauthorised caller cannot even contend for it (audit C-2).
  PERFORM fn_require_capability(p_cycle_id, 'allocation.run');

  -- FR-DEC-004: an advisory lock scoped to the cycle. Two concurrent allocations would
  -- interleave writes and produce a matching that is neither run's result.
  IF NOT pg_try_advisory_xact_lock(hashtext('allocation:' || p_cycle_id::text)) THEN
    RAISE EXCEPTION 'ALLOCATION_IN_PROGRESS' USING ERRCODE = 'raise_exception';
  END IF;

  SELECT count(*) INTO v_blockers FROM fn_allocation_preflight(p_cycle_id);
  IF v_blockers > 0 THEN
    RAISE EXCEPTION 'PREFLIGHT_FAILED: % blocking item(s)', v_blockers
      USING ERRCODE = 'raise_exception';
  END IF;

  SELECT id INTO v_score_run
    FROM score_runs WHERE cycle_id = p_cycle_id ORDER BY computed_at DESC LIMIT 1;

  -- Working set, materialised so the loop reads a frozen snapshot. Reading live tables inside
  -- the loop would let a concurrent edit change the ranking midway through.
  CREATE TEMP TABLE alloc_pref ON COMMIT DROP AS
    SELECT ap.applicant_id,
           ap.department_id,
           ap.rank AS pref_rank,
           s.final_score,
           s.recommendation_count,
           s.score_spread,
           a.submitted_at,
           ('CRITERION_FLOOR' = ANY(s.flags)) AS excluded
      FROM applicant_preferences ap
      JOIN applicants a ON a.id = ap.applicant_id
      JOIN departments d ON d.id = ap.department_id AND d.is_active
      JOIN applicant_scores s ON s.applicant_id = ap.applicant_id AND s.score_run_id = v_score_run
     WHERE ap.cycle_id = p_cycle_id
       AND a.state NOT IN ('withdrawn', 'screened_out', 'no_show');

  -- FR-SCR-013: CRITERION_FLOOR is auto-excluded irrespective of rank. Removed BEFORE the
  -- matching rather than filtered after, so an excluded applicant never displaces anyone.
  DELETE FROM alloc_pref WHERE excluded;

  CREATE INDEX idx_alloc_pref_app_rank ON alloc_pref (applicant_id, pref_rank);
  CREATE INDEX idx_alloc_pref_app_dept ON alloc_pref (applicant_id, department_id);

  -- ON COMMIT DROP belongs AFTER the column list.
  CREATE TEMP TABLE alloc_held (
    department_id uuid NOT NULL,
    applicant_id  uuid NOT NULL,
    PRIMARY KEY (applicant_id)
  ) ON COMMIT DROP;

  CREATE TEMP TABLE alloc_rejected (
    applicant_id  uuid NOT NULL,
    department_id uuid NOT NULL,
    PRIMARY KEY (applicant_id, department_id)
  ) ON COMMIT DROP;

  -- Created ONCE and truncated per pass. Creating a temp table inside the loop means DDL on
  -- every iteration and invalidates plpgsql's cached plans each time.
  CREATE TEMP TABLE alloc_round (
    applicant_id  uuid NOT NULL,
    department_id uuid NOT NULL,
    final_score   numeric,
    recommendation_count smallint,
    score_spread  numeric,
    submitted_at  timestamptz
  ) ON COMMIT DROP;

  -- The proposal loop. Each pass: every unmatched applicant proposes to their most-preferred
  -- department that has not yet rejected them; each department then keeps its best `capacity`
  -- proposals and rejects the rest.
  LOOP
    TRUNCATE alloc_round;

    INSERT INTO alloc_round (applicant_id, department_id, final_score,
                             recommendation_count, score_spread, submitted_at)
      SELECT DISTINCT ON (p.applicant_id)
             p.applicant_id, p.department_id, p.final_score,
             p.recommendation_count, p.score_spread, p.submitted_at
        FROM alloc_pref p
       WHERE NOT EXISTS (SELECT 1 FROM alloc_held h WHERE h.applicant_id = p.applicant_id)
         AND NOT EXISTS (SELECT 1 FROM alloc_rejected r
                          WHERE r.applicant_id = p.applicant_id
                            AND r.department_id = p.department_id)
       ORDER BY p.applicant_id, p.pref_rank ASC;

    SELECT count(*) INTO v_proposals FROM alloc_round;
    EXIT WHEN v_proposals = 0;

    -- Departments consider held candidates and new proposals together, and keep the best.
    -- Considering them together is what makes this deferred acceptance rather than
    -- first-come-first-served: a held candidate can be displaced by a better proposal.
    WITH pool AS (
      SELECT h.department_id, h.applicant_id, p.final_score,
             p.recommendation_count, p.score_spread, p.submitted_at
        FROM alloc_held h
        JOIN alloc_pref p ON p.applicant_id = h.applicant_id
                         AND p.department_id = h.department_id
      UNION ALL
      SELECT department_id, applicant_id, final_score,
             recommendation_count, score_spread, submitted_at
        FROM alloc_round
    ), ranked AS (
      SELECT pool.*,
             row_number() OVER (
               PARTITION BY pool.department_id
               -- FR-DEC-006, the TOTAL order. Levels 4 and 5 are arbitrary, and that is
               -- precisely the point: without them the ordering is partial and re-runs can
               -- differ (E8).
               ORDER BY pool.final_score DESC,
                        pool.recommendation_count DESC,
                        pool.score_spread ASC,
                        pool.submitted_at ASC,
                        pool.applicant_id ASC
             ) AS rnk,
             d.capacity
        FROM pool
        JOIN departments d ON d.id = pool.department_id
    )
    INSERT INTO alloc_rejected (applicant_id, department_id)
    SELECT applicant_id, department_id FROM ranked WHERE rnk > capacity
    ON CONFLICT DO NOTHING;

    -- Anyone rejected this round loses their hold.
    DELETE FROM alloc_held h
     USING alloc_rejected r
     WHERE h.applicant_id = r.applicant_id AND h.department_id = r.department_id;

    -- New holds for proposals that survived.
    INSERT INTO alloc_held (department_id, applicant_id)
    SELECT ar.department_id, ar.applicant_id
      FROM alloc_round ar
     WHERE NOT EXISTS (SELECT 1 FROM alloc_rejected r
                        WHERE r.applicant_id = ar.applicant_id
                          AND r.department_id = ar.department_id)
    ON CONFLICT (applicant_id) DO NOTHING;
  END LOOP;

  -- ── Write decisions ───────────────────────────────────────────────────────────────────
  SELECT coalesce(max(version), 0) + 1 INTO v_version
    FROM decisions WHERE cycle_id = p_cycle_id;

  INSERT INTO allocation_runs (
    cycle_id, score_run_id, result_checksum, selected_count, waitlisted_count, rejected_count, run_by
  ) VALUES (p_cycle_id, v_score_run, '', 0, 0, 0, fn_current_user_id())
  RETURNING * INTO v_run;

  -- Matched.
  INSERT INTO decisions (
    cycle_id, applicant_id, version, outcome, department_id, is_proposal, allocation_run_id
  )
  SELECT p_cycle_id, h.applicant_id, v_version, 'selected', h.department_id, true, v_run.id
    FROM alloc_held h;

  -- FR-DEC-008: unmatched applicants are waitlisted per department, ranked by the SAME
  -- ordering. Ranked against their top remaining preference so the cascade has somewhere to
  -- start.
  INSERT INTO decisions (
    cycle_id, applicant_id, version, outcome, department_id, waitlist_rank,
    is_proposal, allocation_run_id
  )
  SELECT p_cycle_id, w.applicant_id, v_version, 'waitlisted', w.department_id, w.rnk,
         true, v_run.id
    FROM (
      SELECT DISTINCT ON (p.applicant_id)
             p.applicant_id, p.department_id,
             row_number() OVER (
               PARTITION BY p.department_id
               ORDER BY p.final_score DESC, p.recommendation_count DESC,
                        p.score_spread ASC, p.submitted_at ASC, p.applicant_id ASC
             )::int AS rnk
        FROM alloc_pref p
       WHERE NOT EXISTS (SELECT 1 FROM alloc_held h WHERE h.applicant_id = p.applicant_id)
       ORDER BY p.applicant_id, p.pref_rank ASC
    ) w;

  -- Auto-excluded (FR-SCR-013). Recorded as a decision rather than an omission, so the reason
  -- is visible and the override path is obvious.
  INSERT INTO decisions (
    cycle_id, applicant_id, version, outcome, is_proposal, allocation_run_id, reason
  )
  SELECT p_cycle_id, s.applicant_id, v_version, 'excluded', true, v_run.id,
         'criterion floor — automatic, subject to override'
    FROM applicant_scores s
   WHERE s.score_run_id = v_score_run
     AND 'CRITERION_FLOOR' = ANY(s.flags)
  ON CONFLICT (applicant_id, version) DO NOTHING;

  -- FR-DEC-007: the checksum is over the ORDERED output, so two runs over unchanged input
  -- produce the same digest. Computed by fn_allocation_checksum, which uses the Postgres
  -- built-in sha256 rather than pgcrypto — Supabase installs pgcrypto outside this function's
  -- pinned search_path (see migration 0029).
  SELECT * INTO v_run FROM fn_set_allocation_checksum(v_run.id);

  v_checksum   := v_run.result_checksum;
  v_selected   := v_run.selected_count;
  v_waitlisted := v_run.waitlisted_count;
  v_rejected   := v_run.rejected_count;

  PERFORM fn_audit(
    p_cycle_id, 'allocation.run', 'allocation_run', v_run.id,
    NULL,
    jsonb_build_object('checksum', v_checksum, 'selected', v_selected,
                       'waitlisted', v_waitlisted, 'excluded', v_rejected,
                       'version', v_version),
    NULL
  );

  RETURN v_run;
END $$;


CREATE OR REPLACE FUNCTION fn_submit_evaluation(
  p_interview_id   uuid,
  p_interviewer_id uuid,
  p_scores         jsonb,           -- [{"criterion_id": "...", "score": 4, "note": "..."}]
  p_remarks        text DEFAULT NULL,
  p_recommended_dept_id uuid DEFAULT NULL
) RETURNS evaluations
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_interview  interviews;
  v_rubric_id  uuid;
  v_eval       evaluations;
  v_expected   int;
  v_provided   int;
  v_weighted   numeric;
  v_scale_min  smallint;
  v_scale_max  smallint;
  v_item       jsonb;
BEGIN
  SELECT * INTO v_interview FROM interviews WHERE id = p_interview_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'interview % not found', p_interview_id USING ERRCODE = 'no_data_found';
  END IF;

  IF v_interview.status NOT IN ('in_progress', 'awaiting_evaluations') THEN
    RAISE EXCEPTION 'INVALID_TRANSITION: interview is %', v_interview.status
      USING ERRCODE = 'raise_exception';
  END IF;

  -- You may only submit as YOURSELF.
  --
  -- p_interviewer_id was taken on trust. The route passes staff.userId, so the live path was
  -- correct — but the function is the boundary, not the route (R-032), and a caller able to
  -- reach it could attribute an evaluation to any member of the panel. Blind evaluation is the
  -- entire point of FR-INT-004, and an evaluation attributed to the wrong interviewer corrupts
  -- both the score and the bias estimate that scoring derives from it.
  IF p_interviewer_id IS DISTINCT FROM fn_current_user_id() THEN
    RAISE EXCEPTION 'TOKEN_INVALID: an evaluation may only be submitted by its own interviewer'
      USING ERRCODE = 'raise_exception';
  END IF;

  -- Only a CURRENT member of THIS panel may evaluate. Checked here, not only by RLS, so the
  -- error is a clear refusal rather than a constraint violation further down.
  --
  -- `left_at IS NULL` was missing, and fn_claim_next already requires it — so an interviewer
  -- removed from a panel mid-session could no longer be given an applicant but could still
  -- score one. The two must agree about who is on the panel.
  IF NOT EXISTS (
    SELECT 1 FROM panel_members pm
     WHERE pm.panel_id = v_interview.panel_id
       AND pm.interviewer_id = p_interviewer_id
       AND pm.left_at IS NULL
  ) THEN
    RAISE EXCEPTION 'RECUSAL_CONFLICT: not a current member of this panel'
      USING ERRCODE = 'raise_exception';
  END IF;

  -- A declared recusal excludes you from SCORING, not merely from being assigned.
  --
  -- fn_claim_next honours recusals when it hands out an applicant (E7), so the normal path
  -- never reaches here. But an interview started before the recusal was declared, or a
  -- directly-supplied interview id, would let a recused interviewer score the person they
  -- recused themselves from — which is the one outcome the recusal exists to prevent
  -- (FR-QUE-007, FR-INT-006).
  IF EXISTS (
    SELECT 1 FROM recusals r
     WHERE r.interviewer_id = p_interviewer_id
       AND r.applicant_id = v_interview.applicant_id
  ) THEN
    RAISE EXCEPTION 'RECUSAL_CONFLICT: you have recused yourself from this applicant'
      USING ERRCODE = 'raise_exception';
  END IF;

  -- FR-INT-008: one evaluation per interviewer per interview.
  IF EXISTS (
    SELECT 1 FROM evaluations
     WHERE interview_id = p_interview_id
       AND interviewer_id = p_interviewer_id
       AND submitted_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'INVALID_TRANSITION: you have already submitted for this interview'
      USING ERRCODE = 'raise_exception';
  END IF;

  -- The rubric pinned at interview start (E17). Falling back to the active rubric here would
  -- reintroduce exactly the mid-session split the pinning prevents.
  v_rubric_id := v_interview.rubric_id;
  IF v_rubric_id IS NULL THEN
    RAISE EXCEPTION 'interview % has no pinned rubric — it was not started correctly',
      p_interview_id USING ERRCODE = 'raise_exception';
  END IF;

  SELECT scale_min, scale_max INTO v_scale_min, v_scale_max
    FROM rubrics WHERE id = v_rubric_id;

  SELECT count(*) INTO v_expected FROM rubric_criteria WHERE rubric_id = v_rubric_id;
  SELECT count(*) INTO v_provided FROM jsonb_array_elements(p_scores);

  -- FR-INT-020.
  IF v_provided <> v_expected THEN
    RAISE EXCEPTION 'every criterion must be scored: expected %, got %', v_expected, v_provided
      USING ERRCODE = 'raise_exception';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_scores) LOOP
    IF NOT EXISTS (
      SELECT 1 FROM rubric_criteria
       WHERE id = (v_item ->> 'criterion_id')::uuid AND rubric_id = v_rubric_id
    ) THEN
      RAISE EXCEPTION 'criterion % does not belong to the pinned rubric',
        v_item ->> 'criterion_id' USING ERRCODE = 'raise_exception';
    END IF;

    IF (v_item ->> 'score')::smallint NOT BETWEEN v_scale_min AND v_scale_max THEN
      RAISE EXCEPTION 'score % is outside the rubric scale %–%',
        v_item ->> 'score', v_scale_min, v_scale_max USING ERRCODE = 'raise_exception';
    END IF;
  END LOOP;

  INSERT INTO evaluations (
    cycle_id, interview_id, interviewer_id, rubric_id, remarks, recommended_dept_id, submitted_at
  ) VALUES (
    v_interview.cycle_id, p_interview_id, p_interviewer_id, v_rubric_id,
    p_remarks, p_recommended_dept_id, now()
  )
  RETURNING * INTO v_eval;

  INSERT INTO score_items (evaluation_id, criterion_id, score, note)
  SELECT v_eval.id, (e ->> 'criterion_id')::uuid, (e ->> 'score')::smallint, e ->> 'note'
    FROM jsonb_array_elements(p_scores) e;

  -- FR-SCR-001: weighted mean, normalised to 0–100.
  --
  -- Normalising by the SCALE, not by the maximum score, is what makes a 1–5 rubric and a
  -- 1–10 rubric comparable: (score − min) / (max − min) puts every criterion on 0–1 before
  -- weighting. Dividing by max alone would give a rubric with min=1 a floor of 20%.
  SELECT sum(
           ((si.score - v_scale_min)::numeric / (v_scale_max - v_scale_min)) * rc.weight
         ) INTO v_weighted
    FROM score_items si
    JOIN rubric_criteria rc ON rc.id = si.criterion_id
   WHERE si.evaluation_id = v_eval.id;

  UPDATE evaluations SET raw_score = round(v_weighted, 2)
   WHERE id = v_eval.id RETURNING * INTO v_eval;

  PERFORM fn_audit(
    v_interview.cycle_id, 'evaluation.submitted', 'evaluation', v_eval.id,
    NULL,
    jsonb_build_object('interview_id', p_interview_id, 'raw_score', v_eval.raw_score),
    NULL
  );

  PERFORM fn_check_interview_complete(p_interview_id);

  RETURN v_eval;
END $$;

COMMIT;
